def now_iso() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%S%z")


def safe_name(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9._ -]+", "_", str(value)).strip() or "unnamed"


def ascii_comment(value: str) -> str:
    """OpenCore Comment values are intentionally ASCII-only for broad validator compatibility."""
    text = str(value).replace("—", "-").replace("–", "-").replace("→", "->")
    return text.encode("ascii", "replace").decode("ascii")


def hex_to_bytes(value: str) -> bytes:
    cleaned = re.sub(r"[^0-9A-Fa-f]", "", value or "")
    if len(cleaned) % 2:
        raise ValueError(f"Hex data must contain an even number of digits: {value!r}")
    return bytes.fromhex(cleaned)


def bytes_to_hex(value: Any) -> str:
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).hex().upper()
    return str(value)


def deep_get(obj: Any, *keys: str) -> Any:
    current = obj
    for key in keys:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def recursive_values(obj: Any) -> Iterable[Any]:
    if isinstance(obj, dict):
        for key, value in obj.items():
            yield key
            yield value
            yield from recursive_values(value)
    elif isinstance(obj, list):
        for item in obj:
            yield item
            yield from recursive_values(item)


def search_report_text(report: Any, patterns: Iterable[str]) -> list[str]:
    haystack = "\n".join(str(x) for x in recursive_values(report)).lower()
    return [p for p in patterns if p.lower() in haystack]


def parse_pci_id(text: str) -> tuple[str, str] | tuple[None, None]:
    m = re.search(r"(?:VEN[_=&]?|vendor[ :=])([0-9A-Fa-f]{4}).{0,100}?(?:DEV[_=&]?|device[ :=])([0-9A-Fa-f]{4})", text or "", re.I)
    if m:
        return m.group(1).lower(), m.group(2).lower()
    return None, None


def detect_cpu(report: dict[str, Any]) -> str:
    candidates = ["CPU", "Processor", "Name", "Codename"]
    cpu_sections: list[Any] = []
    for key in candidates:
        value = report.get(key)
        if value is not None:
            cpu_sections.append(value)
    for x in recursive_values(report):
        s = str(x)
        if any(tok in s.lower() for tok in ("intel core", "amd ryzen", "xeon", "pentium", "celeron")):
            return s
    return " ".join(str(x) for x in cpu_sections[:5]) or "Unknown CPU"


def detect_gpus(report: dict[str, Any]) -> list[str]:
    out: list[str] = []
    for x in recursive_values(report):
        s = str(x)
        if any(term in s.lower() for term in ("graphics", "radeon", "geforce", "iris xe", "uhd graphics", "intel hd")):
            if len(s) < 240 and s not in out:
                out.append(s)
    return out[:24]


def detect_devices(report: dict[str, Any], keywords: tuple[str, ...]) -> list[str]:
    out = []
    for x in recursive_values(report):
        s = str(x)
        if any(k.lower() in s.lower() for k in keywords) and len(s) < 260:
            if s not in out:
                out.append(s)
    return out[:40]


def macos_name(version: str) -> str:
    for number, name in SAFE_MACOS_TARGETS:
        if version == number or version.startswith(number + "."):
            return name
    return version


def flatten_device_inventory(report: dict[str, Any]) -> list[dict[str, Any]]:
    """Convert loosely structured sniffer output into a predictable inventory."""
    result = []
    for key, value in report.items():
        if isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    record = dict(item)
                    record.setdefault("_section", key)
                    result.append(record)
        elif isinstance(value, dict):
            for subkey, item in value.items():
                if isinstance(item, list):
                    for row in item:
                        if isinstance(row, dict):
                            record = dict(row)
                            record.setdefault("_section", f"{key}/{subkey}")
                            result.append(record)
    return result


