class BuilderError(RuntimeError):
    pass


class Logger:
    def __init__(self, widget: Optional[scrolledtext.ScrolledText] = None):
        self.widget = widget
        self.q: queue.Queue[str] = queue.Queue()

    def attach(self, widget: scrolledtext.ScrolledText) -> None:
        self.widget = widget

    def write(self, message: str = "", level: str = "INFO") -> None:
        line = str(message)
        self.q.put(line)
        if self.widget is None:
            print(line)
            return
        try:
            self.widget.after(0, self._drain)
        except Exception:
            pass

    def _drain(self) -> None:
        if self.widget is None:
            return
        try:
            while True:
                line = self.q.get_nowait()
                self.widget.configure(state="normal")
                self.widget.insert("end", line + "\n")
                self.widget.see("end")
                self.widget.configure(state="disabled")
        except queue.Empty:
            pass

    def section(self, number: int | str, title: str) -> None:
        self.write("")
        self.write(f"[{number}] {title}")
        self.write("=" * min(90, max(30, len(title) + 8)))


